USE SCHEMA VIGIL.CORE;
CREATE OR REPLACE TABLE POLICY_CLAUSES (DOC_ID STRING, CLAUSE_NO STRING, DOC_TITLE STRING, CLAUSE_TITLE STRING, CLAUSE_TEXT STRING, CITATION STRING);
- Doubtful: NPA for more than 12 months.
- Loss: an asset identified as uncollectible.$$,$$POL-CR-001 Clause 3.1$$),
($$POL-CR-001$$,$$3.2$$,$$POL-CR-001 — NPA Classification & Provisioning$$,$$Provisioning$$,$$- Substandard: 15% of the outstanding amount.
- Doubtful: 25% to 100% of the outstanding amount, depending on the period in the doubtful category.
- Loss: 100% of the outstanding amount.$$,$$POL-CR-001 Clause 3.2$$),
($$POL-CR-001$$,$$4.1$$,$$POL-CR-001 — NPA Classification & Provisioning$$,$$Evidentiary Standard$$,$$The finding must cite the loan account ID, days past due, outstanding amount, the classification and the provisioning amount calculated.$$,$$POL-CR-001 Clause 4.1$$),
($$POL-LIQ-001$$,$$1.1$$,$$POL-LIQ-001 — Basel III Liquidity Coverage Ratio (LCR) Compliance$$,$$Purpose$$,$$This policy sets the bank's minimum liquidity standard under Basel III.$$,$$POL-LIQ-001 Clause 1.1$$),
($$POL-LIQ-001$$,$$2.1$$,$$POL-LIQ-001 — Basel III Liquidity Coverage Ratio (LCR) Compliance$$,$$LCR Requirement$$,$$LCR = High Quality Liquid Assets (HQLA) ÷ Net Cash Outflows over the next 30 days. The bank must maintain an LCR of 100% or more at all times.$$,$$POL-LIQ-001 Clause 2.1$$),
($$POL-LIQ-001$$,$$3.1$$,$$POL-LIQ-001 — Basel III Liquidity Coverage Ratio (LCR) Compliance$$,$$Breach Classification$$,$$Any daily snapshot with LCR below 100% is classified as a BREACH.$$,$$POL-LIQ-001 Clause 3.1$$),
($$POL-LIQ-001$$,$$3.2$$,$$POL-LIQ-001 — Basel III Liquidity Coverage Ratio (LCR) Compliance$$,$$ALCO Escalation$$,$$A breach must be escalated to the Asset-Liability Committee (ALCO) within 4 hours of detection.$$,$$POL-LIQ-001 Clause 3.2$$),
($$POL-LIQ-001$$,$$4.1$$,$$POL-LIQ-001 — Basel III Liquidity Coverage Ratio (LCR) Compliance$$,$$Remediation Documentation$$,$$The bank must document the cause of the breach, the remediation actions and the expected date of return to compliance.$$,$$POL-LIQ-001 Clause 4.1$$),
($$POL-LIQ-001$$,$$4.2$$,$$POL-LIQ-001 — Basel III Liquidity Coverage Ratio (LCR) Compliance$$,$$Evidentiary Standard$$,$$The finding must cite the snapshot date, the HQLA amount, the net cash outflows and the computed LCR.$$,$$POL-LIQ-001 Clause 4.2$$);
SELECT (SELECT COUNT(*) FROM POLICY_CLAUSES) clauses, SNOWFLAKE.CORTEX.COMPLETE('llama3.1-8b','Reply with the single word OK') cortex_test;
